  matchesBuiltin: boolean;
}

exports.returns:
({
  /// 是否需要写 profile.modelMetadata（false = 当前配置已是目标态）
  needsSave: boolean;
  /// 保存动作的语义：写自定义覆盖 / 清掉自定义改用内置 / 无需操作
  effect: "custom" | "builtin" | "none";
  /// 按钮文案
  label: string;
  /// hover 说明：为什么可点或为什么不可点
  title: string;
})

